'use strict';
// Each authored trail is independently checked for its letter transformation.
const PUZZLES = [
{title:'A change of heart',start:'HEART',steps:[["EARTH","A whole world, or just a handful in a flowerpot.","Our home planet."],["WATER","It can run for miles without taking a step.","It flows from a tap."],["STEAM","A kettle lets it off; so might an angry person.","Water in its gaseous form."]]},
{title:'Off the beaten path',start:'TRAIL',steps:[["TRIAL","It can end in a verdict or turn you into a subscriber.","A judge may preside over one."],["TRAIN","A line of thought, or a line of carriages.","A railway vehicle."],["GIANT","A fairy-tale villain with a towering advantage.","Jack meets one above the beanstalk."]]},
{title:'Something in the air',start:'NIGHT',steps:[["THING","An object whose name has gone missing from your memory.","A general word for an object."],["THINK","Do this outside the box when the usual ideas fail.","What you do when solving this."],["THANK","Give someone credit with a grateful word.","You ___ someone for a gift."]]},
{title:'Small wonders',start:'SPARE',steps:[["PEARS","Orchard fruit that sounds like it comes in twos.","Green or yellow cousins of apples."],["SPEAR","A weapon whose business end gets straight to the point.","A long shaft used for thrusting or throwing."],["SPARK","One may start an argument; another starts a fire.","A little flash from flint."]]},
{title:'All at sea',start:'COAST',steps:[["COATS","Painters apply them; people put them on.","Wear these over your clothes."],["BOATS","They have bows that never fire arrows.","Small vessels on water."],["BOOST","What a flat battery and low morale might both need.","An increase or encouragement."]]},
{title:'A clean slate',start:'STONE',steps:[["NOTES","They can be passed in class or held by a singer.","You might jot these in a notebook."],["TONES","Change these, and the same words can sound kinder.","Voices can have warm or harsh ones."],["ONSET","An ending has its opposite at this point.","The beginning of an illness or season."]]},
{title:'The great outdoors',start:'PLANT',steps:[["PLANE","It may fly over a workshop or smooth wood inside one.","An aircraft."],["PANEL","A wall section, or the experts sitting in judgment.","A group of experts at a conference."],["PETAL","A flower can lose one each time a lover asks a question.","A rose has many of these."]]},
{title:'A fresh perspective',start:'SMILE',steps:[["LIMES","Tart green wedges with a regular job behind the bar.","Sour fruits used in a mojito."],["MILES","You can put these on a car without loading its boot.","A unit longer than a kilometer."],["SLIME","The goo a movie monster might leave as a calling card.","A sticky toy you can stretch."]]},
{title:'Bright ideas',start:'LIGHT',steps:[["NIGHT","It falls without breaking a single bone.","The opposite of day."],["THING","An unnamed object, or a fashion when it becomes the latest one.","Pass me that ___ over there."],["THINK","Do this twice before making a rash decision.","Ponder or reason."]]},
{title:'Ready, set, grow',start:'SEED',steps:[["DEEDS","They can prove your character or your ownership.","Good ___ help other people."],["NEEDS","They belong on the shopping list before the wants.","Food and shelter are basic ones."],["DENSE","Like a forest with little room between its trees.","The opposite of sparse."]]},
{title:'In good time',start:'HASTE',steps:[["HEATS","Early races in which only some competitors go through.","Qualifying races held before a final."],["WHEAT","A field of it may end up as a row of loaves.","Bread is commonly made from it."],["WATCH","It can have hands, or be what you do with your eyes.","Observe, or a timepiece on your wrist."]]},
{title:'Creature comforts',start:'BEAR',steps:[["BARE","Like a cupboard with nothing left to offer.","Barefoot means your feet are this."],["BREAD","Something you can earn, then spend at a bakery.","A loaf from a bakery."],["BEARD","Growth that can turn a clean-cut chin into a hiding place.","Facial hair below the mouth."]]},
{title:'Written in the stars',start:'STAR',steps:[["START","A sudden fright, or the first step in a long project.","Begin."],["SMART","A compliment to your mind or the way you dress.","Clever or intelligent."],["STREAM","It can flow through a valley or bring a film to your screen.","Smaller than a river."]]},
{title:'A quiet moment',start:'LISTEN',steps:[["SILENT","Like an old film whose dialogue you have to read.","The opposite of noisy."],["TINSEL","A festive tree's sparkle, sold by the strand.","Sparkly Christmas decoration."],["INLETS","Where the sea reaches inland through narrow openings.","Small coastal bays or waterways."]]},
{title:'Room to bloom',start:'GARDEN',steps:[["DANGER","The reason a warning sign earns its place.","A warning sign alerts you to this."],["RANGED","Varied from one extreme to another.","Prices ___ from low to high."],["GRADE","A pupil hopes for a high one; a cyclist may dread a steep one.","A teacher gives you an A, B, or C."]]},
{title:'A silver lining',start:'CLOUD',steps:[["COULD","It promises a possibility, but never a certainty.","The past tense of can."],["COLD","An illness you catch, or a reception you would rather avoid.","How ice feels."],["GOLD","What a champion and a prospector might both go home with.","The metal of a first-place medal."]]},
{title:'A slice of life',start:'LEAST',steps:[["SLATE","A roof may be covered in it; a fresh start wipes it clean.","A dark, layered stone."],["STALE","Like yesterday's bread or a joke everyone has heard.","Bread left out too long becomes this."],["TALES","They may be fairy, tall, or told out of school.","Fairy ___ begin once upon a time."]]}
];
const day=Math.floor(Date.now()/86400000),dateKey=new Date().toISOString().slice(0,10),dailyIndex=((day-20705)%PUZZLES.length+PUZZLES.length)%PUZZLES.length;
let db;try{db=JSON.parse(localStorage.getItem('wordshift-v1'))||{games:{}}}catch{db={games:{}}}if(!db.games)db={games:{}};
let mode='daily',index=dailyIndex,currentView='daily',inputValue='',message='',error=false;
const main=document.querySelector('#main'),modal=document.querySelector('#modal');
function save(){try{localStorage.setItem('wordshift-v1',JSON.stringify(db))}catch{toast('Progress could not be saved in this browser.')}}
function key(){return mode==='daily'?'daily:'+dateKey:'practice:'+index}
function game(){let k=key();return db.games[k]||(db.games[k]={step:0,hints:0,mistakes:0,reveals:0,help:{},solved:false,checked:false})}
function diff(a,b){let aa=a.split(''),bb=b.split('');for(let i=aa.length-1;i>=0;i--){const j=bb.indexOf(aa[i]);if(j>=0){aa.splice(i,1);bb.splice(j,1)}}return{remove:aa.join(''),add:bb.join('')}}
function metrics(){const all=Object.values(db.games).filter(g=>g.solved);let streak=0,d=day;if(!db.games['daily:'+new Date(d*86400000).toISOString().slice(0,10)]?.solved)d--;while(db.games['daily:'+new Date(d*86400000).toISOString().slice(0,10)]?.solved){streak++;d--}return{total:all.length,perfect:all.filter(g=>!g.hints&&!g.mistakes&&!g.reveals).length,streak}}
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',3000)}
function openModal(html){document.querySelector('#modal-content').innerHTML=html;modal.showModal()}
function how(){openModal(`<span class="eyebrow">A little mental somersault</span><h2>Change the letters.<br>Find the next word.</h2><ol><li>Start with the word on the board.</li><li>Follow the letter instruction: add, remove, or swap the letters shown. Then <b>rearrange all the letters</b> to answer the clue.</li><li>Your answer becomes the starting word for the next shift. Solve all three to finish.</li></ol><div class="example"><strong>CAT</strong> &nbsp; + R &nbsp; → &nbsp; <strong>CART</strong><br><small>“A little vehicle you push.”</small></div><p>No timer. No lives to lose. Hints are always here. A perfect solve uses no hints, reveals, or incorrect guesses.</p><button class="primary modal-action" onclick="modal.close()">Let’s play ↗</button>`)}
function showStats(){let m=metrics();openModal(`<span class="eyebrow">Your little rituals, adding up</span><h2>A mind in motion.</h2><div class="stat-grid"><div><b>${m.total}</b><span>Puzzles solved</span></div><div><b>${m.streak}</b><span>Daily streak</span></div><div><b>${m.perfect}</b><span>Perfect solves</span></div></div><p>Progress is saved on this device and browser. Daily puzzles reset at midnight UTC. Practice puzzles count toward solves, but not your daily streak.</p>`)}
function sidebar(){let m=metrics();return `<aside class="sidebar"><section class="note"><div class="symbol" aria-hidden="true">✳</div><h2>Same letters.<br>New possibilities.</h2><p>A little shuffle. A different meaning. Let your mind take the scenic route.</p><button onclick="how()">Show me how it works ↗</button></section><section class="mini-card"><div class="eyebrow">Your daily ritual</div><div class="mini-metrics"><div class="metric"><strong>${m.streak}</strong><span>day streak</span></div><div class="metric"><strong>${m.total}</strong><span>solved</span></div></div><p>A few minutes for a fresher mind.<br>Progress saved on this device.</p></section></aside>`}
function setNav(view){currentView=view;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view))}
function render(){setNav(mode==='daily'?'daily':'collection');const p=PUZZLES[index],g=game();main.innerHTML=`<div class="intro"><div><div class="eyebrow">${mode==='daily'?'Your daily dose of wordplay':'The collection · No waiting required'}</div><h1>${mode==='daily'?'A little change of mind.':p.title}</h1><p>Three connected clues. One word that keeps on changing.</p></div><div class="date">${mode==='daily'?new Date().toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}):'Practice #'+String(index+1).padStart(2,'0')}<span>${mode==='daily'?'A fresh shift every day':'Take it at your own pace'}</span></div></div><div class="layout"><div><section class="game"><div class="game-top"><span class="badge">${mode==='daily'?'The daily shift':'Practice shift'}</span><div class="steps" aria-label="Shift ${Math.min(g.step+1,3)} of 3">${[0,1,2].map(i=>(i?'<span class="step-line"></span>':'')+`<span class="step ${g.step>i||g.solved?'done':g.step===i?'current':''}">${g.step>i||g.solved?'✓':i+1}</span>`).join('')}</div></div><div id="play" class="play-area fade"></div><div class="game-bottom"><span>✧ No rush. Just a little word magic.</span><span>3 shifts · ${p.start.length}–${Math.max(p.start.length,...p.steps.map(s=>s[0].length))} letters</span></div></section><div class="under-game"><span>${mode==='daily'?'One puzzle. A small daily escape.':'A little practice goes a long way.'}</span><button onclick="collection()">Explore the collection ↗</button></div></div>${sidebar()}</div>`;renderPlay()}
function renderPlay(){const p=PUZZLES[index],g=game(),el=document.querySelector('#play');if(g.solved){el.innerHTML=`<div class="success"><div class="success-icon">✳</div><div class="eyebrow">All three shifts complete</div><h2>${!g.hints&&!g.mistakes&&!g.reveals?'A perfect little shift.':'Look at that. You shifted.'}</h2><p>${p.title} — complete.<br>${g.mistakes} incorrect ${g.mistakes===1?'guess':'guesses'} · ${g.hints} hints · ${g.reveals} reveals</p><div class="result-path">${[p.start,...p.steps.map(s=>s[0])].map(w=>`<span>${w}</span>`).join('<small aria-hidden="true">→</small>')}</div><div class="result-actions"><button class="primary" onclick="share()">Share your result ↗</button><button class="secondary" onclick="collection()">Keep playing in the collection</button></div><p>${mode==='daily'?'Your next daily shift arrives at midnight UTC.':'Practice makes possibilities.'}</p></div>`;return}
const n=g.step,step=p.steps[n],source=n?p.steps[n-1][0]:p.start,op=diff(source,step[0]);if(g.checked){el.innerHTML=`<div class="success"><div class="success-icon">${g.help[n]?.revealed?'↗':'✓'}</div><div class="eyebrow">Shift ${n+1} ${g.help[n]?.revealed?'revealed':'solved'}</div><div class="solved-word">${step[0].split('').map(c=>`<span class="tile">${c}</span>`).join('')}</div><p>${step[1]}<br>${step[2]}</p><button class="primary check" onclick="next()">${n===2?'See your result':'On to shift '+(n+2)} <span>→</span></button></div>`;return}
el.innerHTML=`<div class="source-label">${n?'Your last answer':'Your starting word'}</div><div class="source">${source}</div><div class="operation">${op.remove?`<b class="remove">− ${op.remove}</b>`:''}${op.add?`<b class="add">+ ${op.add}</b>`:''}${op.add||op.remove?'<span>then rearrange</span>':'<span>↔ &nbsp; Rearrange only</span>'}</div><div class="down" aria-hidden="true">↓</div><h2 class="clue">${step[1]}</h2><div class="letter-count">${step[0].length} letters</div><form id="answer-form"><div class="answer-wrap"><div class="tiles" id="tiles" aria-hidden="true"></div><input id="answer" aria-label="Answer for shift ${n+1}, ${step[0].length} letters" autocomplete="off" autocapitalize="characters" spellcheck="false" maxlength="${step[0].length}" inputmode="text" aria-describedby="feedback"></div><div class="feedback ${error?'error':''}" id="feedback" role="status">${message||hintText()}</div><button class="primary check" type="submit">Check my word <span>↵</span></button></form><div class="hint-row"><button class="text-btn" onclick="hint()">☼ &nbsp; ${g.help[n]?.count>=2?'Hints shown':'A little nudge'}</button><button class="text-btn" onclick="reveal()">Reveal this shift</button></div>`;
const inp=document.querySelector('#answer');inp.value=inputValue;inp.addEventListener('input',()=>{inputValue=inp.value.toUpperCase().replace(/[^A-Z]/g,'').slice(0,step[0].length);inp.value=inputValue;drawTiles()});inp.addEventListener('focus',drawTiles);inp.addEventListener('blur',drawTiles);document.querySelector('#answer-form').addEventListener('submit',e=>{e.preventDefault();check()});drawTiles()}
function drawTiles(){let len=PUZZLES[index].steps[game().step][0].length;document.querySelector('#tiles').innerHTML=Array.from({length:len},(_,i)=>`<span class="tile ${inputValue[i]?'filled':''} ${i===Math.min(inputValue.length,len-1)&&document.activeElement?.id==='answer'?'focus':''}">${inputValue[i]||''}</span>`).join('')}
function hintText(){const g=game(),h=g.help[g.step]?.count||0,s=PUZZLES[index].steps[g.step];return h===1?s[2]:h>=2?`${s[2]} Starts with ${s[0][0]}.`:''}
function feedback(t,bad=false){message=t;error=bad;const f=document.querySelector('#feedback');f.textContent=t;f.classList.toggle('error',bad)}
function check(){const g=game(),answer=PUZZLES[index].steps[g.step][0];if(inputValue.length!==answer.length){feedback(`Find a ${answer.length}-letter word first.`,true);return}if(inputValue!==answer){g.mistakes++;save();feedback('Not quite. Follow the letter change and try again.',true);document.querySelector('#answer').focus();return}g.checked=true;message='';error=false;save();renderPlay()}
function next(){const g=game();g.checked=false;g.step++;if(g.step===3){g.solved=true;g.completedAt=new Date().toISOString()}inputValue='';message='';error=false;save();render()}
function hint(){const g=game();g.help[g.step] ||= {count:0};if(g.help[g.step].count<2){g.help[g.step].count++;g.hints++;save()}feedback(hintText())}
function reveal(){openModal(`<span class="eyebrow">A helping hand</span><h2>Reveal this shift?</h2><p>We’ll show the answer and its explanation. You can still finish the puzzle, but this won’t count as a perfect solve.</p><button class="primary modal-action" id="confirm-reveal">Show the answer</button><button class="secondary modal-action" onclick="modal.close()">I’ll keep thinking</button>`);document.querySelector('#confirm-reveal').onclick=()=>{const g=game();g.help[g.step] ||= {count:0};g.help[g.step].revealed=true;g.reveals++;g.checked=true;save();modal.close();renderPlay()}}
function collection(){setNav('collection');const solved=Object.values(db.games).filter(g=>g.solved).length;main.innerHTML=`<div class="intro"><div><div class="eyebrow">Stay a little curious</div><h1>The collection.</h1><p>${PUZZLES.length} handcrafted trails. Pick a word and see where it takes you.</p></div></div><div class="collection-grid">${PUZZLES.map((p,i)=>{const g=db.games['practice:'+i];return `<button class="puzzle-card" onclick="playPractice(${i})"><div class="eyebrow">Shift ${String(i+1).padStart(2,'0')}</div><div class="card-word">${p.start}</div><h2>${p.title}</h2><div class="card-foot"><span>${g?.solved?'✓ Completed':g?.step||g?.checked?'In progress':'3 connected clues'}</span><span>↗</span></div></button>`}).join('')}</div>`}
function playPractice(i){index=i;mode='practice';inputValue='';message='';error=false;render();window.scrollTo({top:0,behavior:'smooth'})}
async function share(){const g=game();const result=`Wordshift ${mode==='daily'?dateKey:'Practice #'+(index+1)}\n${[0,1,2].map(n=>g.help[n]?.revealed?'🟨':g.help[n]?.count?'🟩':'✳️').join(' ')}\n3/3 shifts · ${g.hints} hints · ${g.mistakes} misses${g.reveals?' · '+g.reveals+' reveals':''}\n${location.origin}`;try{await navigator.clipboard.writeText(result);toast('Result copied. Share a little word magic!')}catch{openModal('<h2>Your result</h2><p>Copy the text below to share.</p><textarea id="share-text" rows="6" style="width:100%;padding:12px;font:14px sans-serif"></textarea>');document.querySelector('#share-text').value=result}}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(b.dataset.view==='collection')collection();else{mode='daily';index=dailyIndex;inputValue='';message='';error=false;render()}});document.querySelectorAll('.brand').forEach(a=>a.onclick=e=>{e.preventDefault();mode='daily';index=dailyIndex;inputValue='';message='';error=false;render()});document.querySelector('#how').onclick=how;document.querySelector('#stats').onclick=showStats;document.querySelector('#close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});document.querySelector('#about').onclick=()=>openModal('<span class="eyebrow">Hello, curious mind</span><h2>Welcome to Wordshift.</h2><p>An original three-step word transformation game. Follow the letter changes, untangle the clues, and discover where a word can take you.</p><p>The daily puzzle rotates through a collection of 17 handcrafted trails at midnight UTC. All trails are also available for practice.</p><p>No account needed. Your progress stays in this browser. Clearing browser data resets your progress.</p>');
render();

function contactConfig(){
  const c=window.WORDSHIFT_CONTACT||{};
  const email=typeof c.email==='string'&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.email)?c.email:'';
  let donationUrl='';try{const u=new URL(c.donationUrl);if(u.protocol==='https:'&&!u.username&&!u.password)donationUrl=u.href}catch{}
  return {email,donationUrl};
}
function contact(){
  const c=contactConfig();
  openModal(`<span class="eyebrow">Good words are worth sharing</span><h2>Got a little word magic?</h2><p class="contact-intro">Suggest a puzzle, say hello, or talk promotions and partnerships.</p><form id="contact-form" class="contact-form"><label>What’s on your mind?<select name="topic" id="contact-topic"><option value="Puzzle suggestion">A puzzle suggestion</option><option value="Promotion or partnership">A promotion or partnership</option><option value="Feedback or bug report">Feedback or a bug report</option><option value="Something else">Something else</option></select></label><div class="contact-pair"><label>Your name<input name="name" autocomplete="name" maxlength="80" required placeholder="What should we call you?"></label><label>Your email<input name="email" type="email" autocomplete="email" maxlength="254" required placeholder="you@example.com"></label></div><label>Your message<textarea name="message" id="contact-message" minlength="10" maxlength="3000" required placeholder="Share your starting word, answer, and clue. Tell us how the letters change!"></textarea></label><p class="form-note" id="contact-status" role="status">${c.email?'This opens your email app with the message ready. Review it and press Send there. This website does not store your contact details.':'Contact is opening soon. Sending will be available once our contact address is connected.'}</p><button class="primary" type="submit" ${c.email?'':'disabled'}>Open email draft <span>↗</span></button></form>`);
  document.querySelector('#contact-topic').addEventListener('change',e=>{document.querySelector('#contact-message').placeholder=e.target.value==='Puzzle suggestion'?'Share your starting word, answer, and clue. Tell us how the letters change!':e.target.value==='Promotion or partnership'?'Tell us about your brand, your idea, and the best way to reach you.':'What would you like us to know?'});
  document.querySelector('#contact-form').addEventListener('submit',e=>{
    e.preventDefault();if(!c.email||!e.target.reportValidity())return;
    const data=new FormData(e.target),name=String(data.get('name')).trim(),reply=String(data.get('email')).trim(),body=String(data.get('message')).trim();
    if(!name||body.length<10){document.querySelector('#contact-status').textContent='Please add your name and a message of at least 10 characters.';return}
    const subject='Wordshift — '+data.get('topic');
    const message='Name: '+name+'\nReply to: '+reply+'\nTopic: '+data.get('topic')+'\n\n'+body;
    location.href='mailto:'+encodeURIComponent(c.email)+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(message);
    document.querySelector('#contact-status').textContent='Your message has not been sent by this website. Finish sending in your email app; your form is still here if you need it.';
  });
}
function support(){
  const c=contactConfig();
  openModal(`<div class="support-heart" aria-hidden="true">♡</div><span class="eyebrow">Keep the words flowing</span><h2>Support a little curiosity.</h2><p>If Wordshift brings a bright spot to your day, you can help make room for more puzzles.</p><section class="support-box"><h3>A small thank-you.</h3><p>Playing is free. Supporting is optional. Either way, we’re glad you’re here.</p></section>${c.donationUrl?'<a id="donation-link" class="primary modal-action" target="_blank" rel="noopener noreferrer">Support Wordshift ↗</a><p class="form-note">You’ll continue to our external donation page to review the amount and payment details.</p>':'<p>Donations aren’t open yet. In the meantime, sharing Wordshift or suggesting a puzzle is a lovely way to help.</p>'}<button class="text-btn support-alt" id="support-suggestion">Share a puzzle idea instead ↗</button>`);
  if(c.donationUrl)document.querySelector('#donation-link').href=c.donationUrl;
  document.querySelector('#support-suggestion').onclick=()=>{modal.close();contact()};
}
document.querySelector('#contact').onclick=contact;
document.querySelector('#support').onclick=support;
